style.css:
@-moz-document domain("youtube.com") {
/* ? Color Variables */
    :root {
        --main-bg: #000014;      /* Your primary navy-black */
        --darker-bg: #000004;    /* The "new gray" replacement */
        --accent-red: #Db0000;   /* Crimson Red */
        --text-main: #Db0000;
        --input-bg: #000020;
    }

    /* ? Global Backgrounds */
    ytd-app, 
    #content, 
    #page-manager, 
    ytd-browse, 
    ytd-watch-flexy,
    #columns,
    ytd-masthead,
    #background.ytd-masthead {
        background-color: var(--main-bg) !important;
    }

    /* ? Sidebar & Panels (The "Gray" areas) */
    ytd-guide-renderer, 
    #guide-content, 
    ytd-mini-guide-renderer,
    #contentContainer,
    #header,
    ytd-active-item-renderer {
        background-color: var(--darker-bg) !important;
    }

    /* ?️ Category Chips (Top Bar under Search) */
    yt-chip-cloud-chip-renderer[chip-style="STYLE_DEFAULT"],
    yt-chip-cloud-chip-renderer[chip-style="STYLE_HOME_FILTER"],
    #chips-content.ytd-feed-filter-chip-bar-renderer {
        background-color: var(--darker-bg) !important;
        border: 1px solid var(--accent-red) !important;
    }

    /* ?️ Hover States (Replacing Gray highlights) */
    ytd-guide-entry-renderer:hover,
    ytd-menu-service-item-renderer:hover,
    .ytp-menuitem:hover,
    #endpoint.yt-simple-endpoint.ytd-guide-entry-renderer:hover {
        background-color: rgba(219, 0, 0, 0.1) !important; /* Subtle red tint */
    }

    /* ? Top Bar & Borders */
    #masthead-container {
        background-color: var(--main-bg) !important;
        border-bottom: 1px solid var(--accent-red) !important;
    }

    /* ? Text & Headings */
    #video-title, 
    #title, 
    yt-formatted-string, 
    span, 
    label, 
    #content-text,
    .title.ytd-shelf-renderer,
    #channel-title,
    #owner-name,
    #description-text {
        color: var(--text-main) !important;
    }

    /* ? Search Bar */
    #container.ytd-searchbox, 
    #search-icon-legacy.ytd-searchbox {
        background-color: var(--darker-bg) !important;
        border: 1px solid var(--accent-red) !important;
    }
    
    input#search {
        color: var(--text-main) !important;
    }

    /* ? Buttons & Subs */
    #subscribe-button button,
    .yt-spec-button-shape-next--filled {
        background-color: var(--accent-red) !important;
        color: #000 !important;
    }

    /* ?️ Icons */
    yt-icon, 
    .yt-spec-icon-shape,
    #logo-icon,
    .ytp-svg-fill {
        color: var(--accent-red) !important;
        fill: var(--accent-red) !important;
    }

    /* ? PROTECTION: No filters on video/avatars */
    ytd-thumbnail img, 
    .video-stream, 
    #avatar, 
    .yt-img-shadow,
    #img.ytd-thumbnails {
        filter: none !important;
    }

    /* ? Player & Scrollbar */
    .ytp-play-progress, 
    .ytp-scrubber-button {
        background-color: var(--accent-red) !important;
    }

    ::-webkit-scrollbar {
        width: 10px;
    }
    ::-webkit-scrollbar-track {
        background: var(--main-bg);
    }
    ::-webkit-scrollbar-thumb {
        background: var(--accent-red);
        border-radius: 5px;
    }
}
